INSERT INTO events (title, body, image_url, link_url, sort_order, visible) VALUES ('WU凍桃-紅鈴水蜜桃預購3/2啟動', '各位台灣本田暨關係企業的同仁們，好消息來啦！
福委會這次也是與台中東勢產銷班青農 吳毅健合作，特為同仁帶來東勢另一優質水果&mdash;--紅鈴水蜜桃！這次團購不僅能夠品嚐到的紅鈴水蜜桃（台農7號）是台灣農試所育成、專為中低海拔栽培的優良熱帶水蜜桃，主產期為3至5月，是北半球最早成熟的品種之一  ，還能支持台灣農業發展，一舉兩得！
【紅鈴水蜜桃｜春天的初戀滋味】
它是全台最早成熟的水蜜桃，像春天派來的信使，帶著一抹紅暈、一縷清香，輕輕敲醒你的味蕾。
✨ 紅鈴小檔案品種：台農7號
產季：3月初～4月底（3/2開始預購，3月中旬開始出貨）
口感：果肉細軟、入口即化
香氣：清甜淡雅，帶有花香尾韻
特色：全台最早，稀有度破表！', 'uploads/1/2/7/2/127268237/1_orig.jpg', '', 7, 1);
INSERT INTO events (title, body, image_url, link_url, sort_order, visible) VALUES ('曲禾酒莊春節活動', '即日起到曲禾酒莊消費用信用卡結帳，就有機會獲得10％的臺東金幣回饋哦！數量有限，先搶先贏！ 申請回饋流程： ．消費結帳之前要先用手機號碼註冊成為TTPUSH會員（已經是會員的朋友可以省略這個步驟） ．完成刷卡之後提供手機號碼（※必需跟TTPUSH註冊用的手機號碼為同一個號碼！） ．等待3天後臺東金幣就會自動撥入TTPUSH的會員帳號裡。 臺東金幣是什麼：只要是到TTPUSH特約店家消費，都可以折抵消費的虛擬貨幣！大部份的台東地區店家都可以使用喲！詳情請上「踢一下，臺東金幣掉出來」粉專（https://www.facebook.com/TTpushgivemecoin）！
​即日起到2026/3/1止來曲禾酒莊參加梅酒、梅醋DIY，購買曲禾商品享9折！這是針對今年農業易遊網的「馬上出發！新春農遊走春趣」特別設計的優惠企劃，所以需要搭配農遊體驗才能享有這次的優惠喲！ 愛心提醒：結帳的時候請出示粉專優惠公告！
體驗活動預約：https://calendar.app.google/WfAoK34NYitrYXZa8
粉專優惠公告：https://www.facebook.com/share/p/1F6fHhLdP5/', 'uploads/1/2/7/2/127268237/965339054_orig.png', '', 8, 1);
